using System;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonCatRosterVerification
    {
        static void Check(bool value,string message){if(!value)throw new Exception(message);}
        public static void BuildAndVerify()
        {
            PythonCatRosterLayout.Build();var p=UnityEngine.Object.FindObjectOfType<ContentPreview>();p.Initialize();var c=p.GetComponent<PythonStateClient>();var f=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",f).SetValue(c,p);
            var state=PythonServiceSetup.Sample();state.instance_id="cat-roster-ui";state.can_set_shifts=true;state.required_action="";Array.Resize(ref state.cats,12);for(int i=5;i<12;i++)state.cats[i]=new PythonCatState{cat_id="extra-"+i,name="猫"+i,health_status="healthy",activity="cafe",stamina=70,max_stamina=100,fatigue=15,stress=7};state.cats[1].working=false;state.cats[2].activity="general_dispatch";state.cats[2].activity_label="一般派遣中";state.cats[3].health_status="sick";state.cats[3].health_label="病気";state.cats[4].activity="missing";state.cats[4].activity_label="家出中";state.seats=new PythonSeatState[0];state.items=new PythonItems{shop=new PythonItemShop[0],owned=new PythonOwnedItem[0]};Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",f).Invoke(c,new object[]{state});apply();p.GetComponent<PythonPreparationPanel>().Close();var roster=p.GetComponent<PythonCatRoster>();var service=p.GetComponent<PythonServiceScreen>();var detail=p.GetComponent<PythonCatDetailsPanel>();var scroll=service.rosterPanel.GetComponent<ScrollRect>();
            Check(roster.Count==12 && roster.GetCard(0).stateText.text.Contains("出勤") && roster.GetCard(1).stateText.text.Contains("休養") && roster.GetCard(2).stateText.text.Contains("一般派遣中") && roster.GetCard(3).stateText.text.Contains("療養") && roster.GetCard(4).stateText.text.Contains("家出中"),"Activity labels");Check(roster.GetCard(5).stateText.text.Contains("ストレス 7"),"Stress omitted");Check(!roster.GetCard(2).work.interactable && !roster.GetCard(3).work.interactable,"Unavailable shifts enabled");Canvas.ForceUpdateCanvases();Check(scroll.content.rect.height>scroll.viewport.rect.height,"Roster cannot scroll");foreach(var card in roster.content.GetComponentsInChildren<PythonCatCard>(true))if(card.gameObject.activeSelf)Check(card.stateText.preferredHeight<=card.stateText.rectTransform.rect.height+1,"Card status clipped");Capture(p,"CatRosterStates");scroll.verticalNormalizedPosition=.25f;roster.GetCard(8).details.onClick.Invoke();Check(detail.title.text.Contains("猫8") && detail.panel.transform.Find("Details Card/Close").GetComponentInChildren<Text>().text=="猫一覧へ戻る","Wrong cat or return caption");detail.care.onClick.Invoke();var items=p.GetComponent<PythonItemsPanel>();Check(items.panel.activeSelf,"Care did not open");apply();Check(items.panel.transform.GetSiblingIndex()==items.panel.transform.parent.childCount-1,"Polling obscured care");items.Close();Check(detail.panel.activeSelf && detail.title.text.Contains("猫8"),"Care lost detail");Capture(p,"CatRosterDetails");detail.panel.transform.Find("Details Card/Close").GetComponent<Button>().onClick.Invoke();Check(!detail.panel.activeSelf && !service.ShowingSeats && Mathf.Abs(scroll.verticalNormalizedPosition-.25f)<.01f,"Roster position lost");
            state.can_set_shifts=false;state.seats=new[]{new PythonSeatState{seat_id="s1",cat_id=state.cats[0].cat_id,customer_id="guest-1",customer_name="佐藤さん"}};apply();Check(service.ShowingSeats,"Service view missing");service.GetSeatCard(0).details.onClick.Invoke();Check(detail.panel.transform.Find("Details Card/Close").GetComponentInChildren<Text>().text=="席一覧へ戻る","Seat origin lost");detail.Close();Check(service.ShowingSeats,"Seat return switched to roster");
            service.ShowCats();roster.GetCard(0).details.onClick.Invoke();typeof(PythonStateClient).GetField("online",f).SetValue(c,false);p.PythonConnectionError("test");Check(!detail.care.interactable && !detail.interact.interactable,"Offline care allowed");apply();var menu=p.GetComponent<PythonMenuPanel>();menu.Open();apply();Check(!detail.panel.activeSelf && menu.panel.activeSelf,"Polling reopened detail over menu");menu.Close();detail.ResetSelection();Check(!detail.panel.activeSelf,"Load reset retained detail");Check(typeof(PythonStateClient).GetField("pending",f).GetValue(c)==null,"Browsing changed game");Debug.Log("CAT_CAFE_CAT_ROSTER_UI_OK: states / stress / guards / scrolling / care / same cat / roster return / seat return / offline / reset");
        }
        static void Capture(ContentPreview p,string name){Canvas.ForceUpdateCanvases();typeof(ContentPreviewSetup).GetMethod("CaptureCanvas",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{p,"Logs/"+name+".png"});}
    }
}
